            if (!other.data_.empty()) {
                std::memcpy(data_.data(), other.data_.data(), other.data_.size() * sizeof(Entry));
                std::memcpy(power_data_.data(), other.power_data_.data(), other.power_data_.size() * sizeof(Entry));
